    Sprite MakeSprite(int shape){var t=new Texture2D(32,32,TextureFormat.RGBA32,false){filterMode=FilterMode.Point,wrapMode=TextureWrapMode.Clamp};for(int y=0;y<32;y++)for(int x=0;x<32;x++){float dx=Mathf.Abs(x-15.5f),dy=Mathf.Abs(y-15.5f);bool on=shape==0||(shape==1?dx*dx+dy*dy<225:dx+dy<15);t.SetPixel(x,y,on?Color.white:Color.clear);}t.Apply();return Sprite.Create(t,new Rect(0,0,32,32),new Vector2(.5f,.5f),32);}
    void BuildAudio(){sfx=gameObject.AddComponent<AudioSource>();sfx.playOnAwake=false;sfx.volume=.32f;ambient=gameObject.AddComponent<AudioSource>();ambient.loop=true;ambient.volume=.045f;ambient.clip=Tone("Wind",6f,70,true);ambient.Play();}
    AudioClip Tone(string name,float length,float frequency,bool noise=false){int rate=22050,n=Mathf.CeilToInt(rate*length);var data=new float[n];float brown=0;var random=new System.Random(name.GetHashCode());for(int i=0;i<n;i++){float fade=Mathf.Min(1,i/(rate*.01f),(n-i)/(rate*.01f));if(noise){brown=Mathf.Clamp(brown+((float)random.NextDouble()*2-1)*.025f,-.3f,.3f);data[i]=brown*fade;}else data[i]=Mathf.Sin(i*frequency*Mathf.PI*2/rate)*fade*Mathf.Exp(-4f*i/n);}var clip=AudioClip.Create(name,n,1,rate,false);clip.SetData(data,0);return clip;}

