        var bottom=Box(canvas.transform,"Message Panel",new Vector2(0,20),new Vector2(920,84),new Vector2(.5f,0),new Vector2(.5f,0));message=Label(bottom.transform,"Message","",21,TextAnchor.MiddleCenter,Vector2.zero,new Vector2(880,60));
        prompt=Label(canvas.transform,"Prompt","",20,TextAnchor.MiddleCenter,new Vector2(0,116),new Vector2(760,44));prompt.color=AtlasPalette.Gold;prompt.rectTransform.anchorMin=prompt.rectTransform.anchorMax=new Vector2(.5f,0);prompt.rectTransform.pivot=new Vector2(.5f,0);
        terrainReadout=Label(canvas.transform,"Terrain","",16,TextAnchor.LowerLeft,new Vector2(20,116),new Vector2(380,40));terrainReadout.color=AtlasPalette.FadedParchment;terrainReadout.rectTransform.anchorMin=terrainReadout.rectTransform.anchorMax=Vector2.zero;terrainReadout.rectTransform.pivot=Vector2.zero;
        journal=Label(canvas.transform,"Journal","",15,TextAnchor.LowerRight,new Vector2(-20,116),new Vector2(520,92));journal.color=AtlasPalette.FadedParchment;journal.rectTransform.anchorMin=journal.rectTransform.anchorMax=Vector2.one;journal.rectTransform.pivot=Vector2.one;
        seedReadout=Label(canvas.transform,"Seed","",14,TextAnchor.UpperRight,new Vector2(-20,-230),new Vector2(420,30));seedReadout.rectTransform.anchorMin=seedReadout.rectTransform.anchorMax=Vector2.one;seedReadout.rectTransform.pivot=Vector2.one;
        advisor=Label(canvas.transform,"Cartographer","",16,TextAnchor.LowerCenter,new Vector2(0,164),new Vector2(820,42));advisor.color=AtlasPalette.Gold;advisor.rectTransform.anchorMin=advisor.rectTransform.anchorMax=new Vector2(.5f,0);advisor.rectTransform.pivot=new Vector2(.5f,0);
        toastPanel=Box(canvas.transform,"Toast",new Vector2(0,-115),new Vector2(600,56),new Vector2(.5f,1),new Vector2(.5f,1));toast=Label(toastPanel.transform,"ToastText","",19,TextAnchor.MiddleCenter,Vector2.zero,new Vector2(560,44));toastPanel.SetActive(false);
        AddVignette(canvas.transform);
        flash=Panel(canvas.transform,"Discovery Flash",Color.clear).GetComponent<Image>();flash.raycastTarget=false;
        titlePanel=Panel(canvas.transform,"Title",AtlasPalette.Scrim);var sun=new GameObject("Seventh Sun",typeof(RectTransform),typeof(Image));sun.transform.SetParent(titlePanel.transform,false);sun.GetComponent<RectTransform>().sizeDelta=new Vector2(150,150);sun.GetComponent<RectTransform>().anchoredPosition=new Vector2(0,205);sun.GetComponent<Image>().sprite=circle;sun.GetComponent<Image>().color=AtlasPalette.Gold;for(int i=0;i<12;i++){var ray=new GameObject("Sun Ray",typeof(RectTransform),typeof(Image));ray.transform.SetParent(titlePanel.transform,false);var rr=ray.GetComponent<RectTransform>();rr.sizeDelta=new Vector2(10,i%2==0?44:28);rr.anchoredPosition=new Vector2(Mathf.Sin(i*Mathf.PI/6)*112,205+Mathf.Cos(i*Mathf.PI/6)*112);rr.localEulerAngles=new Vector3(0,0,-i*30);ray.GetComponent<Image>().color=new Color(AtlasPalette.Gold.r,AtlasPalette.Gold.g,AtlasPalette.Gold.b,.5f);}var tt=Label(titlePanel.transform,"TitleText","ATLAS OF THE\nSEVENTH SUN",58,TextAnchor.MiddleCenter,new Vector2(0,55),new Vector2(1100,170));tt.color=AtlasPalette.Gold;Label(titlePanel.transform,"Sub","CHART THE UNKNOWN  •  TRADE WITH HONOR  •  RETURN WITH A LEGEND",20,TextAnchor.MiddleCenter,new Vector2(0,-60),new Vector2(1050,60));MakeButton(titlePanel.transform,"BEGIN EXPEDITION",new Vector2(0,-155),StartGame);MakeButton(titlePanel.transform,"FIELD GUIDE",new Vector2(0,-238),ToggleHelp);
        pausePanel=Panel(canvas.transform,"Pause",AtlasPalette.Scrim);Label(pausePanel.transform,"PauseText","EXPEDITION PAUSED",38,TextAnchor.MiddleCenter,new Vector2(0,155),new Vector2(900,90));MakeButton(pausePanel.transform,"RESUME",new Vector2(0,65),TogglePause);MakeButton(pausePanel.transform,"RESTART",new Vector2(0,-20),StartGame);MakeButton(pausePanel.transform,"FIELD GUIDE",new Vector2(0,-105),ToggleHelp);MakeButton(pausePanel.transform,"MUTE  [M]",new Vector2(-195,-190),ToggleMute);MakeButton(pausePanel.transform,"SHAKE  [K]",new Vector2(195,-190),ToggleShake);pausePanel.SetActive(false);
        helpPanel=Panel(canvas.transform,"Field Guide",AtlasPalette.Scrim);Label(helpPanel.transform,"GuideText","FIELD GUIDE\n\nWASD / ARROWS — Travel     E / SPACE — Parley or resupply\nQ — Scout nearby fog (2 uses)     C — Make camp (2 uses)\nESC — Pause     H — Guide     M — Mute     K — Screen shake\n\nPlains: 1 provision • Desert: 2 provisions + 2 days\nForest: 3 provisions + reduced sight • Sea: 2 provisions\nMountain ridges are impassable — find a pass around them.\nThe gold route is your cartographer's least-cost safe path.\nRed hostile patrols hunt every two steps; keep your distance.\nThe rust rival advances every three steps and surveys cities for a smaller reward.\nEvery expedition creates a new map, passes, and patrol deployment.\nDiscover all four cities, secure 120 gold, then return west.\n\nPress H or ESC to close",20,TextAnchor.MiddleCenter,Vector2.zero,new Vector2(1180,700));helpPanel.SetActive(false);
        endPanel=Panel(canvas.transform,"End",AtlasPalette.Scrim);endPanel.SetActive(false);}
    GameObject Box(Transform p,string n,Vector2 pos,Vector2 size,Vector2 anchor,Vector2 pivot){var go=new GameObject(n,typeof(RectTransform),typeof(Image),typeof(Outline));go.transform.SetParent(p,false);var r=go.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=anchor;r.pivot=pivot;r.anchoredPosition=pos;r.sizeDelta=size;go.GetComponent<Image>().color=new Color(AtlasPalette.Ink.r,AtlasPalette.Ink.g,AtlasPalette.Ink.b,.88f);var o=go.GetComponent<Outline>();o.effectColor=new Color(AtlasPalette.Gold.r,AtlasPalette.Gold.g,AtlasPalette.Gold.b,.32f);o.effectDistance=new Vector2(2,-2);return go;}
    Image Bar(Transform p,string n,Vector2 pos,Color c){var bg=new GameObject(n+" Track",typeof(RectTransform),typeof(Image));bg.transform.SetParent(p,false);var r=bg.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(0,1);r.pivot=new Vector2(0,1);r.anchoredPosition=pos;r.sizeDelta=new Vector2(315,18);bg.GetComponent<Image>().color=AtlasPalette.DeepInk;var fill=new GameObject(n+" Fill",typeof(RectTransform),typeof(Image));fill.transform.SetParent(bg.transform,false);var f=fill.GetComponent<RectTransform>();f.anchorMin=Vector2.zero;f.anchorMax=Vector2.one;f.offsetMin=f.offsetMax=Vector2.zero;fill.GetComponent<Image>().color=c;Label(bg.transform,n,n.ToUpperInvariant(),13,TextAnchor.MiddleLeft,new Vector2(0,-18),new Vector2(315,18));return fill.GetComponent<Image>();}
    Text Label(Transform p,string n,string v,int size,TextAnchor a,Vector2 pos,Vector2 dims){var go=new GameObject(n,typeof(RectTransform),typeof(Text),typeof(Shadow));go.transform.SetParent(p,false);var r=go.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(.5f,.5f);r.sizeDelta=dims;r.anchoredPosition=pos;var t=go.GetComponent<Text>();t.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");t.text=v;t.fontSize=size;t.alignment=a;t.color=AtlasPalette.Parchment;t.fontStyle=FontStyle.Bold;t.raycastTarget=false;var sh=go.GetComponent<Shadow>();sh.effectColor=new Color(AtlasPalette.DeepInk.r,AtlasPalette.DeepInk.g,AtlasPalette.DeepInk.b,.8f);sh.effectDistance=new Vector2(2,-2);return t;}
    GameObject Panel(Transform p,string n,Color c){var go=new GameObject(n,typeof(RectTransform),typeof(Image));go.transform.SetParent(p,false);var r=go.GetComponent<RectTransform>();r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=r.offsetMax=Vector2.zero;go.GetComponent<Image>().color=c;return go;}
    void MakeButton(Transform p,string text,Vector2 pos,UnityEngine.Events.UnityAction action){var go=new GameObject(text,typeof(RectTransform),typeof(Image),typeof(Button),typeof(Outline));go.transform.SetParent(p,false);var r=go.GetComponent<RectTransform>();r.sizeDelta=new Vector2(360,68);r.anchoredPosition=pos;go.GetComponent<Image>().color=AtlasPalette.Rust;go.GetComponent<Button>().onClick.AddListener(()=>{Play(.12f,520);action();});var o=go.GetComponent<Outline>();o.effectColor=AtlasPalette.Gold;o.effectDistance=new Vector2(2,-2);Label(go.transform,"Text",text,23,TextAnchor.MiddleCenter,Vector2.zero,r.sizeDelta);}

    void ShowTitle(){SetHUD(false);titlePanel.SetActive(true);}void SetHUD(bool a){hud.transform.parent.gameObject.SetActive(a);objective.transform.parent.gameObject.SetActive(a);message.transform.parent.gameObject.SetActive(a);prompt.gameObject.SetActive(a);terrainReadout.gameObject.SetActive(a);journal.gameObject.SetActive(a);seedReadout.gameObject.SetActive(a);advisor.gameObject.SetActive(a);}void StartGame(){title=false;ended=false;paused=false;Time.timeScale=1;titlePanel.SetActive(false);endPanel.SetActive(false);pausePanel.SetActive(false);helpPanel.SetActive(false);SetHUD(true);Generate();}
    void Generate(){foreach(var go in world)if(go)Destroy(go);world.Clear();fog.Clear();sites.Clear();enemies.Clear();waterMarks.Clear();beacons.Clear();journalEntries.Clear();seed=UnityEngine.Random.Range(100000,999999);rng=new System.Random(seed);float sx=(seed%997)*.013f,sy=(seed%499)*.019f;map=new Terrain[W,H];trailRoot=NewWorld("Trail");routeRoot=NewWorld("Advisor route");for(int x=0;x<W;x++)for(int y=0;y<H;y++){float n=Mathf.PerlinNoise(x*.14f+sx,y*.14f+sy);float detail=Mathf.PerlinNoise(x*.31f+sy,y*.31f+sx)*.08f;Terrain t=x<4?Terrain.Sea:n+detail<.31f?Terrain.Desert:n+detail<.49f?Terrain.Plains:n+detail<.69f?Terrain.Forest:Terrain.Mountain;map[x,y]=t;}Vector2Int[] landmarks={new(3,H/2),new(8,6),new(16,16),new(25,7),new(30,17),new(31,3)};foreach(var landmark in landmarks)EnsureReachable(landmarks[0],landmark);for(int x=0;x<W;x++)for(int y=0;y<H;y++)Tile(x,y,map[x,y]);DrawCoasts();DrawDawnwatch();pos=landmarks[0];rivalPos=landmarks[5];playerSteps=0;provisions=140;shownProvision=140;morale=75;shownMorale=75;gold=0;discoveries=0;score=0;scouts=2;camps=2;days=1;AddSite(landmarks[1],"River Confederacy",20,AtlasPalette.Jade);AddSite(landmarks[2],"Sunstone Mission",28,AtlasPalette.Desert);AddSite(landmarks[3],"Red Mesa Citadel",35,AtlasPalette.Rust);AddSite(landmarks[4],"The Seventh City",90,AtlasPalette.Gold);explorer=SpriteObject("Explorer",circle,AtlasPalette.DeepInk,new Vector3(pos.x+.07f,pos.y-.07f,-.34f),.78f,7);var body=AddMark(explorer.transform,diamond,AtlasPalette.Gold,.68f,9);AddMark(body.transform,circle,AtlasPalette.Parchment,.28f,10);BuildRival();BuildEnemies(3+rng.Next(0,3));AddAmbientInk();Reveal(2);MarkTrail();AddJournal("Day 1 — Landfall at Dawnwatch");SetMessage("Your ship anchors at Dawnwatch. Mountain walls and hostile patrols guard the inland routes.");ShowToast("NEW WORLD  •  MAP CODE "+seed);UpdateView(true);}

    void EnsureReachable(Vector2Int start,Vector2Int goal){map[start.x,start.y]=Terrain.Plains;map[goal.x,goal.y]=Terrain.Plains;if(HasLandRoute(start,goal))return;var p=start;bool horizontalFirst=rng.NextDouble()>.5;while(p!=goal){if((horizontalFirst&&p.x!=goal.x)||p.y==goal.y)p.x+=Math.Sign(goal.x-p.x);else p.y+=Math.Sign(goal.y-p.y);if(map[p.x,p.y]==Terrain.Mountain)map[p.x,p.y]=rng.NextDouble()>.35?Terrain.Plains:Terrain.Forest;}}
    bool HasLandRoute(Vector2Int start,Vector2Int goal){var open=new Queue<Vector2Int>();var seen=new HashSet<Vector2Int>{start};open.Enqueue(start);Vector2Int[] dirs={Vector2Int.up,Vector2Int.right,Vector2Int.down,Vector2Int.left};while(open.Count>0){var p=open.Dequeue();if(p==goal)return true;foreach(var d in dirs){var n=p+d;if(n.x<1||n.x>=W-1||n.y<1||n.y>=H-1||map[n.x,n.y]==Terrain.Mountain||!seen.Add(n))continue;open.Enqueue(n);}}return false;}
    GameObject NewWorld(string n){var go=new GameObject(n);world.Add(go);return go;}GameObject SpriteObject(string n,Sprite s,Color c,Vector3 at,float scale,int order){var go=NewWorld(n);var sr=go.AddComponent<SpriteRenderer>();sr.sprite=s;sr.color=c;sr.sortingOrder=order;go.transform.position=at;go.transform.localScale=Vector3.one*scale;return go;}GameObject AddMark(Transform p,Sprite s,Color c,float scale,int order,Vector3? local=null){var go=new GameObject("Ink mark",typeof(SpriteRenderer));go.transform.SetParent(p,false);go.transform.localPosition=local??Vector3.zero;go.transform.localScale=Vector3.one*scale;var sr=go.GetComponent<SpriteRenderer>();sr.sprite=s;sr.color=c;sr.sortingOrder=order;return go;}
    void Tile(int x,int y,Terrain t){Color c=t switch{Terrain.Sea=>AtlasPalette.Sea,Terrain.Plains=>AtlasPalette.Plains,Terrain.Forest=>AtlasPalette.Forest,Terrain.Desert=>AtlasPalette.Desert,_=>AtlasPalette.Mountain};SpriteObject("Tile shadow",square,new Color(AtlasPalette.DeepInk.r,AtlasPalette.DeepInk.g,AtlasPalette.DeepInk.b,.35f),new Vector3(x+.06f,y-.06f,.04f),.97f,-1);var tile=SpriteObject($"{t}_{x}_{y}",square,c,new Vector3(x,y,0),.97f,0);TerrainGlyph(tile.transform,t,x,y);var f=SpriteObject("Uncharted",square,AtlasPalette.Fog,new Vector3(x,y,-.2f),.99f,5);fog[new Vector2Int(x,y)]=f;}
    void TerrainGlyph(Transform tile,Terrain t,int x,int y){Color ink=new(AtlasPalette.Ink.r,AtlasPalette.Ink.g,AtlasPalette.Ink.b,t==Terrain.Sea?.32f:.62f);if(t==Terrain.Sea){if((x+y)%2==0){var w=AddMark(tile,square,AtlasPalette.FadedParchment,.3f,1,new Vector3(0,.08f,-.04f));w.transform.localScale=new Vector3(.42f,.055f,1);waterMarks.Add(w.GetComponent<SpriteRenderer>());}return;}if(t==Terrain.Mountain){for(int i=0;i<3;i++){var peak=AddMark(tile,diamond,ink,.44f-i*.055f,1,new Vector3(-.26f+i*.25f,-.03f+Mathf.Abs(1-i)*-.06f,-.04f));peak.transform.localScale=new Vector3(.34f,.58f,1);}var snow=AddMark(tile,diamond,AtlasPalette.FadedParchment,.18f,2,new Vector3(0,.2f,-.05f));snow.transform.localScale=new Vector3(.16f,.2f,1);return;}if(t==Terrain.Forest){if((x+y)%2!=0)return;AddMark(tile,diamond,ink,.27f,1,new Vector3(-.2f,-.03f,-.04f));AddMark(tile,diamond,ink,.34f,1,new Vector3(.02f,.1f,-.04f));AddMark(tile,diamond,ink,.24f,1,new Vector3(.24f,-.08f,-.04f));return;}if(t==Terrain.Desert){if((x+y)%3==0)return;for(int i=0;i<2;i++){var dune=AddMark(tile,circle,ink,.38f,1,new Vector3(i==0?-.18f:.18f,i==0?.1f:-.13f,-.04f));dune.transform.localScale=new Vector3(.48f,.095f,1);}return;}if((x*3+y)%3==0){AddMark(tile,circle,ink,.13f,1,new Vector3(-.18f,.08f,-.04f));AddMark(tile,circle,ink,.1f,1,new Vector3(.16f,-.12f,-.04f));}}
    void DrawCoasts(){for(int x=1;x<W-1;x++)for(int y=1;y<H-1;y++)if(map[x,y]!=Terrain.Sea){if(map[x-1,y]==Terrain.Sea)CoastLine(x-.47f,y,.07f,.9f);if(map[x+1,y]==Terrain.Sea)CoastLine(x+.47f,y,.07f,.9f);if(map[x,y-1]==Terrain.Sea)CoastLine(x,y-.47f,.9f,.07f);if(map[x,y+1]==Terrain.Sea)CoastLine(x,y+.47f,.9f,.07f);}}void CoastLine(float x,float y,float sx,float sy){var c=SpriteObject("Coast ink",square,new Color(AtlasPalette.Parchment.r,AtlasPalette.Parchment.g,AtlasPalette.Parchment.b,.5f),new Vector3(x,y,-.08f),1,2);c.transform.localScale=new Vector3(sx,sy,1);}
    void DrawDawnwatch(){var port=SpriteObject("Dawnwatch harbor",circle,AtlasPalette.Rust,new Vector3(2,H/2f,-.1f),.9f,3);AddMark(port.transform,diamond,AtlasPalette.Parchment,.58f,4);var sail=AddMark(port.transform,diamond,AtlasPalette.Gold,.28f,5,new Vector3(.16f,.18f,-.05f));sail.transform.localScale=new Vector3(.18f,.38f,1);}
    void AddSite(Vector2Int p,string n,int value,Color c){var halo=SpriteObject(n+" halo",circle,new Color(c.r,c.g,c.b,.26f),new Vector3(p.x,p.y,-.1f),1.18f,3);var m=SpriteObject(n,diamond,AtlasPalette.DeepInk,new Vector3(p.x,p.y,-.12f),.88f,4);AddMark(m.transform,diamond,c,.72f,5);AddMark(m.transform,circle,AtlasPalette.Parchment,.28f,6);var beacon=SpriteObject(n+" beacon",circle,new Color(c.r,c.g,c.b,.18f),new Vector3(p.x,p.y,-.11f),1.65f,3);beacons.Add(beacon);sites.Add(new Site{p=p,name=n,gold=value,color=c,marker=m,beacon=beacon});}

    void BuildRival(){rival=SpriteObject("Rival expedition",diamond,AtlasPalette.DeepInk,new Vector3(rivalPos.x,rivalPos.y,-.33f),.82f,8);var banner=AddMark(rival.transform,diamond,AtlasPalette.Rust,.64f,9);banner.transform.localScale=new Vector3(.4f,.72f,1);AddMark(banner.transform,circle,AtlasPalette.Parchment,.25f,10);}
    void BuildEnemies(int count){int attempts=0;while(enemies.Count<count&&attempts++<300){var p=new Vector2Int(rng.Next(7,W-2),rng.Next(2,H-2));if(map[p.x,p.y]==Terrain.Mountain||Vector2Int.Distance(p,pos)<8||sites.Exists(s=>Vector2Int.Distance(s.p,p)<2)||enemies.Exists(e=>Vector2Int.Distance(e.p,p)<3)||FindPath(pos,p).Count==0)continue;var token=SpriteObject("Hostile patrol",circle,AtlasPalette.DeepInk,new Vector3(p.x,p.y,-.32f),.74f,8);var claws=AddMark(token.transform,diamond,AtlasPalette.Danger,.62f,9);claws.transform.localScale=new Vector3(.72f,.32f,1);AddMark(token.transform,diamond,AtlasPalette.Danger,.38f,10,new Vector3(0,.18f,-.03f));enemies.Add(new Enemy{p=p,token=token,stagger=rng.Next(0,2)});}}
    void AddAmbientInk(){for(int i=0;i<18;i++){float x=(float)rng.NextDouble()*W;float y=(float)rng.NextDouble()*H;var line=SpriteObject("Wind stroke",square,new Color(AtlasPalette.Parchment.r,AtlasPalette.Parchment.g,AtlasPalette.Parchment.b,.09f),new Vector3(x,y,-.06f),1,1);line.transform.localScale=new Vector3(.55f+(float)rng.NextDouble()*.7f,.035f,1);waterMarks.Add(line.GetComponent<SpriteRenderer>());}}

    void Update(){pulse+=Time.unscaledDeltaTime;AnimateBars();for(int i=0;i<waterMarks.Count;i++)if(waterMarks[i])waterMarks[i].color=new Color(AtlasPalette.FadedParchment.r,AtlasPalette.FadedParchment.g,AtlasPalette.FadedParchment.b,.12f+Mathf.Sin(pulse*1.8f+i*.7f)*.07f);for(int i=0;i<beacons.Count;i++)if(beacons[i])beacons[i].transform.localScale=Vector3.one*(1.5f+Mathf.Sin(pulse*2.2f+i)*.18f);if(toastPanel.activeSelf)toastPanel.transform.localScale=Vector3.one*(1+Mathf.Sin(pulse*8)*.015f);if(title){var img=titlePanel.transform.Find("Seventh Sun")?.GetComponent<Image>();if(img)img.color=new Color(AtlasPalette.Gold.r,AtlasPalette.Gold.g,AtlasPalette.Gold.b,.75f+Mathf.Sin(pulse*2)*.12f);return;}var k=Keyboard.current;if(k==null)return;if(k.hKey.wasPressedThisFrame)ToggleHelp();if(k.mKey.wasPressedThisFrame)ToggleMute();if(k.kKey.wasPressedThisFrame)ToggleShake();if(helpPanel.activeSelf){if(k.escapeKey.wasPressedThisFrame)ToggleHelp();return;}if(ended)return;if(k.escapeKey.wasPressedThisFrame)TogglePause();if(paused)return;moveCooldown-=Time.deltaTime;Vector2Int d=Vector2Int.zero;if(k.wKey.isPressed||k.upArrowKey.isPressed)d=Vector2Int.up;else if(k.sKey.isPressed||k.downArrowKey.isPressed)d=Vector2Int.down;else if(k.aKey.isPressed||k.leftArrowKey.isPressed)d=Vector2Int.left;else if(k.dKey.isPressed||k.rightArrowKey.isPressed)d=Vector2Int.right;if(d!=Vector2Int.zero&&moveCooldown<=0){Move(d);moveCooldown=stepDelay;}if(k.eKey.wasPressedThisFrame||k.spaceKey.wasPressedThisFrame)Interact();if(k.qKey.wasPressedThisFrame)Scout();if(k.cKey.wasPressedThisFrame)Camp();CameraMotion();foreach(var s in sites)if(!s.found&&s.marker)s.marker.transform.localScale=Vector3.one*(.86f+Mathf.Sin(Time.time*3+s.p.x)*.06f);if(explorer)explorer.transform.localScale=Vector3.one*(1+Mathf.Sin(pulse*3)*.025f);if(rival)rival.transform.localScale=Vector3.one*(1+Mathf.Sin(pulse*4+1)*.035f);foreach(var e in enemies)if(e.token)e.token.transform.localScale=Vector3.one*(.72f+Mathf.Sin(pulse*5+e.p.x)*.055f);}
    void TogglePause(){paused=!paused;Time.timeScale=paused?0:1;pausePanel.SetActive(paused);}int Cost(Terrain t)=>t switch{Terrain.Mountain=>999,Terrain.Forest=>3,Terrain.Sea=>2,Terrain.Desert=>2,_=>1};
    void Move(Vector2Int d){var n=pos+d;if(n.x<1||n.x>=W-1||n.y<1||n.y>=H-1){SetMessage("The expedition cannot cross the edge of the known world.");stepDelay=.2f;return;}Terrain next=map[n.x,n.y];if(next==Terrain.Mountain){SetMessage("An unbroken mountain wall blocks the company. Find a pass around the ridge.");ShowToast("MOUNTAIN RIDGE  •  IMPASSABLE");Play(.12f,150);kick=.14f;stepDelay=.32f;return;}int cost=Cost(next);pos=n;playerSteps++;stepDelay=next==Terrain.Desert?.3f:next==Terrain.Forest?.23f:.16f;if(explorer)explorer.transform.localEulerAngles=new Vector3(0,0,d==Vector2Int.up?0:d==Vector2Int.right?-90:d==Vector2Int.down?180:90);int travelDays=next==Terrain.Desert?2:1;days+=travelDays;provisions-=cost;score+=2;MarkTrail();Play(.07f,300+cost*50);if(next==Terrain.Desert){SetMessage("Loose dunes slow the column. The crossing takes two days.");ShowToast("DUNE CROSSING  •  2 DAYS");}else if(next==Terrain.Forest)SetMessage("The dense canopy narrows the expedition's view.");double eventRoll=rng.NextDouble();if(eventRoll<.04){morale-=4;SetMessage("A hard march tests the company. Morale falls by 4.");AddJournal($"Day {days} — The company endured hardship");kick=.16f;}else if(eventRoll>.965){provisions=Mathf.Min(140,provisions+10);score+=15;SetMessage("Foragers find a hidden cache: +10 provisions.");AddJournal($"Day {days} — Found a supply cache");ShowToast("SUPPLY CACHE  +10");Play(.16f,620);}if(playerSteps%2==0)AdvanceEnemies();if(playerSteps%3==0)AdvanceRival();Reveal(next==Terrain.Forest?1:2);UpdateView();if(provisions<=0||morale<=0)Finish(false,"The expedition can go no farther.");}
    void MarkTrail(){var dot=SpriteObject("Route mark",circle,new Color(AtlasPalette.Parchment.r,AtlasPalette.Parchment.g,AtlasPalette.Parchment.b,.42f),new Vector3(pos.x,pos.y,-.16f),.14f,3);dot.transform.SetParent(trailRoot.transform);}void Reveal(int radius){for(int x=pos.x-radius;x<=pos.x+radius;x++)for(int y=pos.y-radius;y<=pos.y+radius;y++)if(fog.TryGetValue(new Vector2Int(x,y),out var f)){Destroy(f);fog.Remove(new Vector2Int(x,y));}}
    List<Vector2Int> FindPath(Vector2Int start,Vector2Int goal){var open=new List<Vector2Int>{start};var cost=new Dictionary<Vector2Int,int>{{start,0}};var came=new Dictionary<Vector2Int,Vector2Int>();Vector2Int[] dirs={Vector2Int.up,Vector2Int.right,Vector2Int.down,Vector2Int.left};while(open.Count>0){int best=0;for(int i=1;i<open.Count;i++)if(cost[open[i]]+Mathf.Abs(open[i].x-goal.x)+Mathf.Abs(open[i].y-goal.y)<cost[open[best]]+Mathf.Abs(open[best].x-goal.x)+Mathf.Abs(open[best].y-goal.y))best=i;var cur=open[best];open.RemoveAt(best);if(cur==goal)break;foreach(var d in dirs){var next=cur+d;if(next.x<1||next.x>=W-1||next.y<1||next.y>=H-1||map[next.x,next.y]==Terrain.Mountain)continue;int nextCost=cost[cur]+Cost(map[next.x,next.y]);if(cost.TryGetValue(next,out int old)&&old<=nextCost)continue;cost[next]=nextCost;came[next]=cur;if(!open.Contains(next))open.Add(next);}}var path=new List<Vector2Int>();if(start!=goal&&!came.ContainsKey(goal))return path;for(var cur=goal;cur!=start;cur=came[cur])path.Add(cur);path.Reverse();return path;}
    Site NearestSite(Vector2Int from){Site best=null;int bestCost=int.MaxValue;foreach(var s in sites){if(s.found)continue;var path=FindPath(from,s.p);int pathCost=0;foreach(var p in path)pathCost+=Cost(map[p.x,p.y]);if(path.Count>0&&pathCost<bestCost){best=s;bestCost=pathCost;}}return best;}
    void AdvanceRival(){var target=NearestSite(rivalPos);if(target==null)return;var path=FindPath(rivalPos,target.p);if(path.Count>0)rivalPos=path[0];if(rival){Vector3 from=rival.transform.position;Vector3 to=new(rivalPos.x,rivalPos.y,-.33f);StartCoroutine(Slide(rival,from,to));}if(rivalPos==target.p&&!target.found&&!target.rivalSurveyed){target.rivalSurveyed=true;target.marker.GetComponent<SpriteRenderer>().color=AtlasPalette.Rust;SetMessage($"The rival expedition surveys {target.name}. Its richest trade will not wait forever.");ShowToast("RIVAL SURVEY  •  "+target.name.ToUpperInvariant());AddJournal($"Day {days} — Rival flags sighted at {target.name}");Play(.18f,220);kick=.18f;}}
    void AdvanceEnemies(){foreach(var e in enemies){if(e.stagger>0){e.stagger--;continue;}var path=FindPath(e.p,pos);if(path.Count==0)continue;if(path.Count==1){EnemyAttack(e);continue;}var next=path[0];if(enemies.Exists(other=>other!=e&&other.p==next))continue;e.p=next;if(e.token){Vector3 from=e.token.transform.position;Vector3 to=new(e.p.x,e.p.y,-.32f);StartCoroutine(Slide(e.token,from,to));}if(Vector2Int.Distance(e.p,pos)<=1.1f)EnemyAttack(e);}}
    void EnemyAttack(Enemy e){morale-=6;provisions=Mathf.Max(0,provisions-4);e.stagger=2;kick=.3f;Burst(new Vector3(pos.x,pos.y,-.4f),AtlasPalette.Danger);Play(.18f,180);SetMessage("A hostile patrol raids the column: -6 morale and -4 provisions.");ShowToast("PATROL ATTACK  •  MORALE -6");AddJournal($"Day {days} — Repelled a hostile patrol");}
    System.Collections.IEnumerator Slide(GameObject token,Vector3 from,Vector3 to){for(float t=0;t<1;t+=Time.deltaTime/.28f){if(!token)yield break;float e=1-Mathf.Pow(1-t,3);token.transform.position=Vector3.Lerp(from,to,e);yield return null;}if(token)token.transform.position=to;}
    void DrawAdvisorRoute(Site target,List<Vector2Int> path){if(!routeRoot)return;foreach(Transform child in routeRoot.transform)Destroy(child.gameObject);int count=Mathf.Min(7,path.Count);for(int i=0;i<count;i++){var p=path[i];var dot=SpriteObject("Advisor ink",i==count-1?diamond:circle,new Color(AtlasPalette.Gold.r,AtlasPalette.Gold.g,AtlasPalette.Gold.b,.72f-i*.055f),new Vector3(p.x,p.y,-.25f),i==count-1?.22f:.11f,6);dot.transform.SetParent(routeRoot.transform);}if(target==null)advisor.text="CARTOGRAPHER  •  RETURN WEST TO DAWNWATCH";else{int cost=0;foreach(var p in path)cost+=Cost(map[p.x,p.y]);string bearing=target.p.x>pos.x?"EAST":target.p.x<pos.x?"WEST":target.p.y>pos.y?"NORTH":"SOUTH";advisor.text=$"CARTOGRAPHER  •  {bearing} TO {target.name.ToUpperInvariant()}  •  EST. {cost} PROVISIONS";}}
    void Scout(){if(scouts<=0){SetMessage("No scouting parties remain.");return;}scouts--;provisions-=6;Reveal(4);score+=20;ShowToast("REGION SCOUTED");AddJournal($"Day {days} — Surveyed the surrounding country");Play(.2f,700);UpdateView();}
    void Camp(){if(camps<=0){SetMessage("No camp kits remain.");return;}if(provisions<12){SetMessage("You need 12 provisions to make camp.");return;}camps--;days+=2;provisions-=12;morale=Mathf.Min(100,morale+22);score+=10;ShowToast("CAMP MADE  •  MORALE +22");AddJournal($"Day {days} — Rested beneath the stars");Play(.18f,440);UpdateView();}
    void Interact(){var site=sites.Find(s=>Vector2Int.Distance(s.p,pos)<1.5f&&!s.found);if(site!=null){site.found=true;discoveries++;int reward=site.rivalSurveyed?Mathf.Max(10,site.gold-8):site.gold;gold+=reward;score+=reward*3+100;morale=Mathf.Min(100,morale+10);site.marker.transform.localScale*=1.35f;if(site.beacon)site.beacon.SetActive(false);kick=.32f;PlaySting();Burst(site.marker.transform.position,site.color);StartCoroutine(Flash(site.color));SetMessage($"{site.name} enters the atlas. Trade yields {reward} gold and restores 10 morale."+(site.rivalSurveyed?" The rival took the first bargain.":""));AddJournal($"Day {days} — Charted {site.name}");ShowToast($"DISCOVERY {discoveries}/4  •  +{reward} GOLD");}else if(pos.x<=4){provisions=Mathf.Min(140,provisions+55);morale=Mathf.Min(100,morale+15);Play(.18f,520);SetMessage("Dawnwatch refits the expedition: +55 provisions, +15 morale.");AddJournal($"Day {days} — Refit at Dawnwatch");if(gold>=120&&discoveries>=4)Finish(true,"You return with the Seventh City mapped and a legend secured.");}else SetMessage("No delegation waits here. Search for a glowing chart marker.");UpdateView();}
    void Burst(Vector3 c,Color color){for(int i=0;i<18;i++){float a=i*Mathf.PI*2/18;var p=SpriteObject("Discovery spark",diamond,color,c+new Vector3(Mathf.Cos(a),Mathf.Sin(a),-.4f)*.8f,.18f,10);StartCoroutine(Spark(p,a));}}System.Collections.IEnumerator Spark(GameObject p,float a){var start=p.transform.position;for(float t=0;t<1;t+=Time.deltaTime/.65f){if(!p)yield break;p.transform.position=start+new Vector3(Mathf.Cos(a),Mathf.Sin(a),0)*t*1.4f;p.transform.localScale=Vector3.one*.18f*(1-t);yield return null;}if(p)Destroy(p);}void Play(float length,float f){if(muted)return;sfx.pitch=UnityEngine.Random.Range(.94f,1.06f);sfx.PlayOneShot(Tone("SFX"+f,length,f));}void PlaySting(){Play(.14f,523);Invoke(nameof(PlayStingTwo),.1f);}void PlayStingTwo(){Play(.16f,659);Invoke(nameof(PlayStingThree),.1f);}void PlayStingThree(){Play(.22f,784);}
    void CameraMotion(){var target=new Vector3(Mathf.Clamp(pos.x,7,W-7),Mathf.Clamp(pos.y,5,H-5),-10);cameraTarget=Vector3.Lerp(cameraTarget==Vector3.zero?target:cameraTarget,target,1-Mathf.Exp(-7*Time.deltaTime));if(kick>0&&shakeEnabled){kick=Mathf.MoveTowards(kick,0,Time.deltaTime*1.6f);cameraTarget+=(Vector3)UnityEngine.Random.insideUnitCircle*kick;}cam.transform.position=cameraTarget;}
    void UpdateView(bool snap=false){if(explorer)explorer.transform.position=new Vector3(pos.x,pos.y,-.35f);var target=new Vector3(Mathf.Clamp(pos.x,7,W-7),Mathf.Clamp(pos.y,5,H-5),-10);if(snap){cameraTarget=target;cam.transform.position=target;}var terrain=map[pos.x,pos.y];int cost=Cost(terrain);string effect=terrain==Terrain.Desert?"2-DAY CROSSING":terrain==Terrain.Forest?"SIGHT REDUCED":terrain==Terrain.Sea?"ROUGH WATER":"CLEAR GOING";hud.text=$"DAY {days:000}     GOLD {gold:000}     DISCOVERIES {discoveries}/4     SCORE {score:0000}";provisionBar.color=provisions<30?AtlasPalette.Danger:AtlasPalette.Gold;moraleBar.color=morale<25?AtlasPalette.Danger:AtlasPalette.Jade;objective.text=$"THE CROWN'S MANDATE\n\n◈ Chart all four sites   {discoveries}/4\n◈ Secure 120 gold        {gold}/120\n◈ Return west to Dawnwatch\n\n⚔ Hostile patrols         {enemies.Count}\nQ Scout ×{scouts}     C Camp ×{camps}";terrainReadout.text=$"{terrain.ToString().ToUpperInvariant()}  •  COST {cost}  •  {effect}  •  WEST ⟵ DAWNWATCH";seedReadout.text=$"MAP CODE {seed}";var near=sites.Find(s=>Vector2Int.Distance(s.p,pos)<1.5f&&!s.found);prompt.text=near!=null?$"E / SPACE  —  PARLEY AT {near.name.ToUpperInvariant()}":pos.x<=4?"E / SPACE  —  RESUPPLY AT DAWNWATCH":"";journal.text=string.Join("\n",journalEntries);var next=NearestSite(pos);DrawAdvisorRoute(next,next==null?new List<Vector2Int>():FindPath(pos,next.p));}
    void AnimateBars(){shownProvision=Mathf.Lerp(shownProvision,provisions,1-Mathf.Exp(-8*Time.unscaledDeltaTime));shownMorale=Mathf.Lerp(shownMorale,morale,1-Mathf.Exp(-8*Time.unscaledDeltaTime));if(provisionBar)provisionBar.rectTransform.anchorMax=new Vector2(Mathf.Clamp01(shownProvision/140f),1);if(moraleBar)moraleBar.rectTransform.anchorMax=new Vector2(Mathf.Clamp01(shownMorale/100f),1);}
    void AddJournal(string entry){journalEntries.Enqueue(entry);while(journalEntries.Count>3)journalEntries.Dequeue();}
    void AddVignette(Transform canvas){void Band(string n,Vector2 anchor,Vector2 size,Vector2 pos){var b=new GameObject(n,typeof(RectTransform),typeof(Image));b.transform.SetParent(canvas,false);var r=b.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=anchor;r.pivot=anchor;r.sizeDelta=size;r.anchoredPosition=pos;b.GetComponent<Image>().color=new Color(AtlasPalette.DeepInk.r,AtlasPalette.DeepInk.g,AtlasPalette.DeepInk.b,.22f);b.GetComponent<Image>().raycastTarget=false;}Band("Top Shade",new Vector2(.5f,1),new Vector2(1600,22),Vector2.zero);Band("Bottom Shade",new Vector2(.5f,0),new Vector2(1600,18),Vector2.zero);}
    System.Collections.IEnumerator Flash(Color c){for(float t=0;t<1;t+=Time.unscaledDeltaTime/.22f){flash.color=new Color(c.r,c.g,c.b,(1-t)*.42f);yield return null;}flash.color=Color.clear;}
    void ShowToast(string text){toast.text=text;toastPanel.SetActive(true);CancelInvoke(nameof(HideToast));Invoke(nameof(HideToast),2.2f);}void HideToast(){if(toastPanel)toastPanel.SetActive(false);}
    void ToggleHelp(){bool open=!helpPanel.activeSelf;helpPanel.SetActive(open);if(!title&&!ended)Time.timeScale=open?0:(paused?0:1);}
    void ToggleMute(){muted=!muted;ambient.mute=muted;sfx.mute=muted;PlayerPrefs.SetInt("AtlasMute",muted?1:0);ShowToast(muted?"AUDIO MUTED":"AUDIO RESTORED");}
    void ToggleShake(){shakeEnabled=!shakeEnabled;PlayerPrefs.SetInt("AtlasShake",shakeEnabled?1:0);ShowToast(shakeEnabled?"SCREEN SHAKE ON":"SCREEN SHAKE OFF");}
    void LoadPreferences(){muted=PlayerPrefs.GetInt("AtlasMute",0)==1;shakeEnabled=PlayerPrefs.GetInt("AtlasShake",1)==1;ambient.mute=muted;sfx.mute=muted;}
    void SetMessage(string s){message.text=s;CancelInvoke(nameof(ClearMessage));Invoke(nameof(ClearMessage),5);}void ClearMessage(){if(message)message.text="";}void Finish(bool win,string reason){ended=true;Time.timeScale=1;score+=win?Mathf.Max(0,1500-days*8):0;int best=Mathf.Max(PlayerPrefs.GetInt("AtlasBest",0),score);PlayerPrefs.SetInt("AtlasBest",best);endPanel.SetActive(true);foreach(Transform c in endPanel.transform)Destroy(c.gameObject);PlaySting();var r=Label(endPanel.transform,"Result",(win?"THE ATLAS IS COMPLETE":"THE EXPEDITION IS LOST")+"\n\n"+reason+$"\n\nDAYS {days}   •   GOLD {gold}   •   SITES {discoveries}/4\nSCORE {score}   •   BEST {best}",38,TextAnchor.MiddleCenter,new Vector2(0,70),new Vector2(1100,380));r.color=win?AtlasPalette.Gold:AtlasPalette.Danger;MakeButton(endPanel.transform,"SAIL AGAIN",new Vector2(0,-155),StartGame);MakeButton(endPanel.transform,"FIELD GUIDE",new Vector2(0,-238),ToggleHelp);}
}
